29	/** All currency codes the library can bill in, sorted. */
30	export function supportedCurrencies() {
31	  return Object.keys(CURRENCIES).sort();
32	}
33	
34	export function isSupportedCurrency(code) {
35	  return Object.hasOwn(CURRENCIES, code);
36	}
37	
38	/** Throws unless `code` is a currency in the table. */
39	export function assertCurrency(code) {
40	  if (!isSupportedCurrency(code)) {
41	    throw new RangeError(`Unsupported currency: ${code}`);
42	  }
43	}
44	
45	/** Number of decimals in a currency: JPY 0, USD 2, KWD 3. */
46	export function minorUnitDigits(code) {
47	  assertCurrency(code);
48	  return CURRENCIES[code].digits;
49	}
50	
51	/** Minor units in one major unit: JPY 1, USD 100, KWD 1000. */
52	export function minorUnitsPerMajor(code) {
53	  return 10 ** minorUnitDigits(code);
54	}
55	
56	export function currencyName(code) {
