1	/**
2	 * Billing periods. A subscription renews every `intervalMonths` months from
3	 * its anchor date. A period runs from its start up to, but not including, its
4	 * end, and each period starts where the previous one ended.
5	 */
6	
7	import { compareDates, formatIsoDate, parseIsoDate } from './dates.mjs';
8	
9	const MONTH_LENGTHS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
10	
11	function assertInterval(intervalMonths) {
12	  if (!Number.isInteger(intervalMonths) || intervalMonths < 1) {
13	    throw new RangeError(`intervalMonths must be a positive integer, got ${intervalMonths}`);
14	  }
15	}
16	
17	/** The next renewal date after `date`, keeping its day where the month allows. */
18	function nextBoundary(date, intervalMonths) {
19	  const { year, month, day } = parseIsoDate(date);
20	  const monthIndex = year * 12 + (month - 1) + intervalMonths;
21	  const nextYear = Math.floor(monthIndex / 12);
22	  const nextMonth = monthIndex - nextYear * 12;
23	  return formatIsoDate({
24	    year: nextYear,
25	    month: nextMonth + 1,
26	    day: Math.min(day, MONTH_LENGTHS[nextMonth]),
27	  });
28	}
29	
30	/** The period at a zero-based index. */
31	export function periodAt(anchor, intervalMonths, index) {
32	  assertInterval(intervalMonths);
33	  if (!Number.isInteger(index) || index < 0) {
34	    throw new RangeError(`index must be a non-negative integer, got ${index}`);
35	  }
36	  parseIsoDate(anchor);
37	  let start = anchor;
38	  for (let i = 0; i < index; i += 1) start = nextBoundary(start, intervalMonths);
39	  return { index, start, end: nextBoundary(start, intervalMonths) };
40	}
41	
42	/** The first `count` billing periods from the anchor. */
43	export function billingPeriods(anchor, intervalMonths, count) {
44	  assertInterval(intervalMonths);
45	  parseIsoDate(anchor);
46	  const periods = [];
47	  let start = anchor;
48	  for (let index = 0; index < count; index += 1) {
49	    const end = nextBoundary(start, intervalMonths);
50	    periods.push({ index, start, end });
51	    start = end;
52	  }
53	  return periods;
54	}
55	
56	/** The period a date falls in. Dates before the anchor have no period. */
57	export function periodContaining(anchor, intervalMonths, date) {
58	  assertInterval(intervalMonths);
59	  if (compareDates(date, anchor) < 0) {
60	    throw new RangeError(`${date} is before the subscription anchor ${anchor}`);
61	  }
62	  let index = 0;
63	  let start = anchor;
64	  for (;;) {
65	    const end = nextBoundary(start, intervalMonths);
66	    if (compareDates(date, end) < 0) return { index, start, end };
67	    start = end;
68	    index += 1;
69	  }
70	}
71	
72	/** The first `count` renewal dates strictly after `date`. */
73	export function renewalsAfter(anchor, intervalMonths, date, count) {
74	  const renewals = [];
75	  let period = periodContaining(anchor, intervalMonths, date);
76	  while (renewals.length < count) {
77	    renewals.push(period.end);
78	    period = periodContaining(anchor, intervalMonths, period.end);
79	  }
80	  return renewals;
81	}
