1	/**
2	 * Invoices: turns priced lines into a discounted, taxed document whose numbers
3	 * are all integer minor units of a single currency.
4	 */
5	
6	import { allocate } from './allocation.mjs';
7	import { assertCurrency } from './currencies.mjs';
8	import { parseIsoDate } from './dates.mjs';
9	import { assertMinorUnits, sumAmounts } from './money.mjs';
10	import { scaleRounded } from './rounding.mjs';
11	import { applyTax, assertTaxRate, taxSummary } from './tax.mjs';
12	
13	const BASIS_POINTS = 10_000;
14	
15	function normalizeLine(input, position) {
16	  const { description, unitAmount, quantity = 1, taxRateBps = 0, period = null } = input;
17	  if (typeof description !== 'string' || description.length === 0) {
18	    throw new TypeError(`Line ${position} needs a description`);
19	  }
20	  assertMinorUnits(unitAmount, `Line ${position} unitAmount`);
21	  if (!Number.isInteger(quantity) || quantity < 1) {
22	    throw new RangeError(`Line ${position} quantity must be a positive integer`);
23	  }
24	  assertTaxRate(taxRateBps);
25	  const amount = unitAmount * quantity;
26	  assertMinorUnits(amount, `Line ${position} amount`);
27	  return { description, unitAmount, quantity, amount, taxRateBps, period };
28	}
29	
30	/**
31	 * A discount is either { percentBps } or { fixed }, and applies only to lines
32	 * with a positive amount: credit lines and free lines never take any of it.
33	 */
34	function resolveDiscount(discount, base) {
35	  if (discount == null) return 0;
36	  const hasPercent = discount.percentBps !== undefined;
37	  const hasFixed = discount.fixed !== undefined;
38	  if (hasPercent === hasFixed) {
39	    throw new TypeError('A discount needs exactly one of percentBps or fixed');
40	  }
41	  if (hasPercent) {
42	    const { percentBps } = discount;
43	    if (!Number.isInteger(percentBps) || percentBps < 0 || percentBps > BASIS_POINTS) {
44	      throw new RangeError(`Discount must be 0 to 10000 basis points, got ${percentBps}`);
45	    }
46	    return scaleRounded(base, percentBps, BASIS_POINTS);
47	  }
48	  assertMinorUnits(discount.fixed, 'discount');
49	  if (discount.fixed < 0 || discount.fixed > base) {
50	    throw new RangeError(`Discount of ${discount.fixed} does not fit a base of ${base}`);
51	  }
52	  return discount.fixed;
53	}
54	
55	function applyDiscount(lines, discount) {
56	  const weights = lines.map((line) => Math.max(line.amount, 0));
57	  const base = sumAmounts(weights);
58	  const discountTotal = resolveDiscount(discount, base);
59	  const shares = discountTotal === 0 ? lines.map(() => 0) : allocate(discountTotal, weights);
60	  return lines.map((line, position) => ({
61	    ...line,
62	    discount: shares[position],
63	    net: line.amount - shares[position],
64	  }));
65	}
66	
67	/**
68	 * Builds an invoice.
69	 *
70	 * @param {object} input
71	 * @param {string} input.number invoice number
72	 * @param {string} input.customerId
73	 * @param {string} input.currency
74	 * @param {string} input.issueDate ISO date
75	 * @param {object[]} input.lines { description, unitAmount, quantity?, taxRateBps?, period? }
76	 * @param {object} [input.discount] { percentBps } or { fixed }
77	 */
78	export function buildInvoice(input) {
79	  const { number, customerId, currency, issueDate, lines, discount = null } = input;
80	  assertCurrency(currency);
81	  parseIsoDate(issueDate);
82	  if (!number) throw new TypeError('An invoice needs a number');
83	  if (!Array.isArray(lines) || lines.length === 0) {
84	    throw new RangeError('An invoice needs at least one line');
85	  }
86	
87	  const priced = lines.map(normalizeLine);
88	  const taxed = applyTax(applyDiscount(priced, discount));
89	  const summary = taxSummary(taxed);
90	
91	  const subtotal = sumAmounts(taxed.map((line) => line.amount));
92	  const discountTotal = sumAmounts(taxed.map((line) => line.discount));
93	  const netTotal = sumAmounts(taxed.map((line) => line.net));
94	  const taxTotal = sumAmounts(summary.map((row) => row.tax));
95	
96	  return {
97	    number,
98	    customerId,
99	    currency,
100	    issueDate,
101	    lines: taxed,
102	    taxSummary: summary,
103	    subtotal,
104	    discountTotal,
105	    netTotal,
106	    taxTotal,
107	    total: netTotal + taxTotal,
