1	/**
2	 * Credit notes reverse part or all of an invoice's lines. An invoice can have
3	 * any number of them, so each new note is issued against the notes before it.
4	 */
5	
6	import { compareDates, parseIsoDate } from './dates.mjs';
7	import { assertMinorUnits, parseAmount, sumAmounts } from './money.mjs';
8	import { taxForAmount } from './tax.mjs';
9	
10	function assertNotesBelongTo(invoice, notes) {
11	  for (const note of notes) {
12	    if (note.invoiceNumber !== invoice.number) {
13	      throw new RangeError(`Credit note ${note.number} belongs to invoice ${note.invoiceNumber}`);
14	    }
15	  }
16	}
17	
18	/** Per invoice line, the net and tax credited by the given notes. */
19	export function creditedToDate(invoice, notes = []) {
20	  assertNotesBelongTo(invoice, notes);
21	  const credited = invoice.lines.map(() => ({ net: 0, tax: 0 }));
22	  for (const note of notes) {
23	    for (const line of note.lines) {
24	      credited[line.lineIndex].net += line.net;
25	      credited[line.lineIndex].tax += line.tax;
26	    }
27	  }
28	  return credited;
29	}
30	
31	/** Per invoice line, the net amount that can still be credited. */
32	export function remainingCreditable(invoice, notes = []) {
33	  const credited = creditedToDate(invoice, notes);
34	  return invoice.lines.map((line, index) => Math.max(line.amount - credited[index].net, 0));
35	}
36	
37	function requestedAmount(invoice, request, available) {
38	  if (request.amount !== undefined) {
39	    assertMinorUnits(request.amount, 'credit amount');
40	    return request.amount;
41	  }
42	  if (request.amountText !== undefined) return parseAmount(request.amountText, invoice.currency);
43	  return available;
44	}
45	
46	/**
47	 * Issues a credit note. `request.lines` holds { lineIndex, amount } entries;
48	 * amount is a net amount in minor units, or decimal text as amountText. With
49	 * neither, the entry credits everything left on that line.
50	 */
51	export function issueCreditNote(invoice, request, priorNotes = []) {
52	  const { number, date, reason = '', lines } = request;
53	  if (!number) throw new TypeError('A credit note needs a number');
54	  parseIsoDate(date);
55	  if (compareDates(date, invoice.issueDate) < 0) {
56	    throw new RangeError(`Credit note ${number} predates invoice ${invoice.number}`);
57	  }
58	  if (!Array.isArray(lines) || lines.length === 0) {
59	    throw new RangeError('A credit note needs at least one line');
60	  }
61	
62	  const available = remainingCreditable(invoice, priorNotes);
63	  const noteLines = lines.map((entry) => {
64	    const line = invoice.lines[entry.lineIndex];
65	    if (!line) throw new RangeError(`Invoice ${invoice.number} has no line ${entry.lineIndex}`);
66	    if (line.net <= 0) {
67	      throw new RangeError(`Line ${entry.lineIndex} of ${invoice.number} has nothing to credit`);
68	    }
69	
70	    const amount = requestedAmount(invoice, entry, available[entry.lineIndex]);
71	    if (amount <= 0 || amount > line.amount) {
72	      throw new RangeError(`Cannot credit ${amount} on line ${entry.lineIndex} of ${invoice.number}`);
73	    }
74	
75	    const tax = taxForAmount(amount, line.taxRateBps);
76	    available[entry.lineIndex] = Math.max(available[entry.lineIndex] - amount, 0);
77	    return {
78	      lineIndex: entry.lineIndex,
79	      description: line.description,
80	      net: amount,
81	      tax,
82	      gross: amount + tax,
83	    };
84	  });
85	
86	  const netTotal = sumAmounts(noteLines.map((line) => line.net));
87	  const taxTotal = sumAmounts(noteLines.map((line) => line.tax));
88	  return {
89	    number,
90	    invoiceNumber: invoice.number,
91	    currency: invoice.currency,
92	    date,
93	    reason,
94	    lines: noteLines,
95	    netTotal,
96	    taxTotal,
97	    total: netTotal + taxTotal,
98	  };
99	}
100	
101	/** Credits everything still creditable on an invoice's positive lines. */
102	export function creditInvoiceInFull(invoice, request, priorNotes = []) {
103	  const available = remainingCreditable(invoice, priorNotes);
104	  const lines = invoice.lines
105	    .map((line, lineIndex) => ({ line, lineIndex }))
106	    .filter(({ line, lineIndex }) => line.net > 0 && available[lineIndex] > 0)
107	    .map(({ lineIndex }) => ({ lineIndex }));
108	  return issueCreditNote(invoice, { ...request, lines }, priorNotes);
109	}
110	
111	/** What is still owed on an invoice after its credit notes. */
112	export function invoiceBalance(invoice, notes = []) {
113	  assertNotesBelongTo(invoice, notes);
114	  return invoice.total - sumAmounts(notes.map((note) => note.total));
115	}
