1	/**
2	 * Subscriptions tie a plan, a currency and a renewal schedule together, and
3	 * produce the invoices for renewals and mid-period plan changes.
4	 */
5	
6	import { assertCurrency } from './currencies.mjs';
7	import { addMonths, parseIsoDate } from './dates.mjs';
8	import { buildInvoice } from './invoice.mjs';
9	import { priceOf } from './plans.mjs';
10	import { planChangeAmounts } from './proration.mjs';
11	import { periodAt, periodContaining, renewalsAfter } from './schedule.mjs';
12	import { assertTaxRate } from './tax.mjs';
13	
14	function assertSeats(seats) {
15	  if (!Number.isInteger(seats) || seats < 1) {
16	    throw new RangeError(`seats must be a positive integer, got ${seats}`);
17	  }
18	}
19	
20	export function createSubscription(input) {
21	  const {
22	    id,
23	    customerId,
24	    anchor,
25	    plan,
26	    currency,
27	    intervalMonths = 1,
28	    seats = 1,
29	    taxRateBps = 0,
30	    minimumTermMonths = 0,
31	  } = input;
32	  if (!id) throw new TypeError('A subscription needs an id');
33	  parseIsoDate(anchor);
34	  assertCurrency(currency);
35	  assertSeats(seats);
36	  assertTaxRate(taxRateBps);
37	  priceOf(plan, currency);
38	  return Object.freeze({
39	    id,
40	    customerId,
41	    anchor,
42	    plan,
43	    currency,
44	    intervalMonths,
45	    seats,
46	    taxRateBps,
47	    minimumTermMonths,
48	  });
49	}
50	
51	/** The date the customer's minimum commitment runs up to, exclusive. */
52	export function minimumTermEnd(subscription) {
53	  return addMonths(subscription.anchor, subscription.minimumTermMonths);
54	}
55	
56	export function upcomingRenewals(subscription, afterDate, count) {
57	  const { anchor, intervalMonths } = subscription;
58	  return renewalsAfter(anchor, intervalMonths, afterDate, count);
59	}
60	
61	/** The invoice for one whole billing period, by zero-based index. */
62	export function renewalInvoice(subscription, periodIndex, options) {
63	  const { number, issueDate, discount } = options;
64	  const { anchor, intervalMonths, plan, currency, seats, taxRateBps, customerId } = subscription;
65	  const period = periodAt(anchor, intervalMonths, periodIndex);
66	  return buildInvoice({
67	    number,
68	    customerId,
69	    currency,
70	    issueDate: issueDate ?? period.start,
71	    discount,
72	    lines: [
73	      {
74	        description: `${plan.name} (${period.start} to ${period.end})`,
75	        unitAmount: priceOf(plan, currency),
76	        quantity: seats,
77	        taxRateBps,
78	        period,
79	      },
80	    ],
81	  });
82	}
83	
84	/**
85	 * Changes plan or seats mid-period. Returns the invoice for the change, with a
86	 * credit line for the old terms and a charge line for the new ones, and the
87	 * subscription as it stands afterwards.
88	 */
89	export function planChangeInvoice(subscription, change) {
90	  const { changeDate, number, issueDate = changeDate, newPlan, newSeats } = change;
91	  const { anchor, intervalMonths, plan, currency, seats, taxRateBps, customerId } = subscription;
92	  const nextPlan = newPlan ?? plan;
93	  const nextSeats = newSeats ?? seats;
94	  assertSeats(nextSeats);
95	
96	  const period = periodContaining(anchor, intervalMonths, changeDate);
97	  const { credit, charge } = planChangeAmounts({
98	    oldAmount: priceOf(plan, currency) * seats,
99	    newAmount: priceOf(nextPlan, currency) * nextSeats,
100	    period,
101	    changeDate,
102	  });
103	
104	  const invoice = buildInvoice({
105	    number,
106	    customerId,
107	    currency,
108	    issueDate,
109	    lines: [
110	      {
111	        description: `Unused ${plan.name} (${changeDate} to ${period.end})`,
112	        unitAmount: credit,
113	        taxRateBps,
114	        period,
115	      },
116	      {
117	        description: `${nextPlan.name} (${changeDate} to ${period.end})`,
118	        unitAmount: charge,
119	        taxRateBps,
120	        period,
121	      },
122	    ],
123	  });
124	  return {
125	    invoice,
126	    subscription: Object.freeze({ ...subscription, plan: nextPlan, seats: nextSeats }),
127	  };
128	}
