1	/**
2	 * Plain-text statements: the view of an invoice and its credit notes that goes
3	 * out to customers.
4	 */
5	
6	import { invoiceBalance } from './credit-note.mjs';
7	import { formatLongDate } from './dates.mjs';
8	import { formatAmount } from './money.mjs';
9	
10	const DESCRIPTION_WIDTH = 44;
11	const NUMBER_WIDTH = 12;
12	
13	function row(description, ...numbers) {
14	  const cells = numbers.map((value) => String(value).padStart(NUMBER_WIDTH));
15	  return [String(description).padEnd(DESCRIPTION_WIDTH), ...cells].join(' ').trimEnd();
16	}
17	
18	function cell(minor) {
19	  return (minor / 100).toFixed(2);
20	}
21	
22	function ratePercent(rateBps) {
23	  const percent = rateBps / 100;
24	  return `${Number.isInteger(percent) ? percent : percent.toFixed(2)}%`;
25	}
26	
27	function invoiceLines(invoice) {
28	  const header = row('Description', 'Amount', 'Discount', 'Net', 'Tax', 'Gross');
29	  const body = invoice.lines.map((line) =>
30	    row(
31	      line.description,
32	      cell(line.amount),
33	      cell(line.discount),
34	      cell(line.net),
35	      cell(line.tax),
36	      cell(line.gross),
37	    ),
38	  );
39	  return [header, ...body];
40	}
41	
42	function creditNoteLines(invoice, notes) {
43	  const out = [];
44	  for (const note of notes) {
45	    out.push('', `Credit note ${note.number} on ${formatLongDate(note.date)}`);
46	    if (note.reason) out.push(`Reason: ${note.reason}`);
47	    for (const line of note.lines) {
48	      out.push(row(line.description, '', '', cell(-line.net), cell(-line.tax), cell(-line.gross)));
49	    }
50	    out.push(`Credited: ${formatAmount(-note.total, invoice.currency)}`);
51	  }
52	  return out;
53	}
54	
55	export function renderStatement(invoice, notes = []) {
56	  const { currency } = invoice;
57	  const out = [
58	    `Invoice ${invoice.number}`,
59	    `Customer ${invoice.customerId}`,
60	    `Issued ${formatLongDate(invoice.issueDate)}`,
61	    `Currency ${currency}`,
62	    '',
63	    ...invoiceLines(invoice),
64	    '',
65	    `Subtotal: ${formatAmount(invoice.subtotal, currency)}`,
66	    `Discount: ${formatAmount(-invoice.discountTotal, currency)}`,
67	    `Net: ${formatAmount(invoice.netTotal, currency)}`,
68	  ];
69	  for (const { rateBps, taxable, tax } of invoice.taxSummary) {
70	    const base = formatAmount(taxable, currency);
71	    out.push(`Tax at ${ratePercent(rateBps)} on ${base}: ${formatAmount(tax, currency)}`);
72	  }
73	  out.push(`Total: ${formatAmount(invoice.total, currency)}`);
74	  out.push(...creditNoteLines(invoice, notes));
75	  out.push('', `Balance due: ${formatAmount(invoiceBalance(invoice, notes), currency)}`);
76	  return `${out.join('\n')}\n`;
77	}
