/**
 * Billing periods. A subscription renews every `intervalMonths` months from
 * its anchor date. A period runs from its start up to, but not including, its
 * end, and each period starts where the previous one ended.
 *
 * Every boundary is worked out from the anchor, never from the previous
 * boundary, so a short month moves one renewal and leaves the billing day alone.
 */

import { addMonths, compareDates, parseIsoDate } from './dates.mjs';

function assertInterval(intervalMonths) {
  if (!Number.isInteger(intervalMonths) || intervalMonths < 1) {
    throw new RangeError(`intervalMonths must be a positive integer, got ${intervalMonths}`);
  }
}

/** The start of the period at `index`; the end of period `index - 1`. */
function boundaryAt(anchor, intervalMonths, index) {
  return addMonths(anchor, intervalMonths * index);
}

function periodFor(anchor, intervalMonths, index) {
  return {
    index,
    start: boundaryAt(anchor, intervalMonths, index),
    end: boundaryAt(anchor, intervalMonths, index + 1),
  };
}

/** The period at a zero-based index. */
export function periodAt(anchor, intervalMonths, index) {
  assertInterval(intervalMonths);
  if (!Number.isInteger(index) || index < 0) {
    throw new RangeError(`index must be a non-negative integer, got ${index}`);
  }
  parseIsoDate(anchor);
  return periodFor(anchor, intervalMonths, index);
}

/** The first `count` billing periods from the anchor. */
export function billingPeriods(anchor, intervalMonths, count) {
  assertInterval(intervalMonths);
  parseIsoDate(anchor);
  const periods = [];
  for (let index = 0; index < count; index += 1) {
    periods.push(periodFor(anchor, intervalMonths, index));
  }
  return periods;
}

/** The period a date falls in. Dates before the anchor have no period. */
export function periodContaining(anchor, intervalMonths, date) {
  assertInterval(intervalMonths);
  parseIsoDate(anchor);
  if (compareDates(date, anchor) < 0) {
    throw new RangeError(`${date} is before the subscription anchor ${anchor}`);
  }
  const from = parseIsoDate(anchor);
  const to = parseIsoDate(date);
  const months = (to.year - from.year) * 12 + (to.month - from.month);
  // Start a little before the answer, then walk forward to it.
  let index = Math.max(0, Math.floor(months / intervalMonths) - 1);
  for (;;) {
    const period = periodFor(anchor, intervalMonths, index);
    if (compareDates(date, period.end) < 0) return period;
    index += 1;
  }
}

/** The first `count` renewal dates strictly after `date`. */
export function renewalsAfter(anchor, intervalMonths, date, count) {
  const renewals = [];
  let { index } = periodContaining(anchor, intervalMonths, date);
  while (renewals.length < count) {
    renewals.push(boundaryAt(anchor, intervalMonths, index + 1));
    index += 1;
  }
  return renewals;
}

/**
 * Splits an integer amount between lines in proportion to their weights, so
 * that the parts add up to the amount exactly.
 */

import { assertMinorUnits, sumAmounts } from './money.mjs';

function assertWeights(weights) {
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('allocate needs at least one weight');
  }
  for (const weight of weights) {
    if (!Number.isSafeInteger(weight) || weight < 0) {
      throw new RangeError(`Weights must be non-negative integers, got ${weight}`);
    }
  }
}

/**
 * allocate(amount, weights) returns one integer per weight. The amount may be
 * negative. At least one weight has to be positive.
 *
 * Each part starts at its exact share rounded towards zero. The units left over
 * go one each to the lines that lost the most, earlier lines first on a tie. A
 * negative amount mirrors the positive one.
 */
export function allocate(amount, weights) {
  assertMinorUnits(amount);
  assertWeights(weights);
  const totalWeight = sumAmounts(weights);
  if (totalWeight === 0) {
    throw new RangeError('allocate needs at least one positive weight');
  }

  const magnitude = BigInt(Math.abs(amount));
  const total = BigInt(totalWeight);
  const shares = weights.map((weight) => {
    const product = magnitude * BigInt(weight);
    return { whole: product / total, lost: product % total };
  });
  let leftover = magnitude - shares.reduce((sum, share) => sum + share.whole, 0n);

  const order = shares
    .map((share, position) => ({ share, position }))
    .sort((a, b) => {
      if (a.share.lost !== b.share.lost) return a.share.lost > b.share.lost ? -1 : 1;
      return a.position - b.position;
    });
  for (const { share } of order) {
    if (leftover === 0n) break;
    share.whole += 1n;
    leftover -= 1n;
  }

  const sign = amount < 0 ? -1 : 1;
  return shares.map((share) => {
    const part = sign * Number(share.whole);
    return part === 0 ? 0 : part;
  });
}

/**
 * Conversions between integer minor units and the decimal text people read
 * and type, plus a few guarded integer helpers.
 */

import { minorUnitDigits } from './currencies.mjs';

const AMOUNT_PATTERN = /^(-)?(\d{1,3}(?:,\d{3})+|\d+)(?:\.(\d+))?$/;

function groupThousands(digits) {
  return digits.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

/** Throws unless `value` is an integer count of minor units. */
export function assertMinorUnits(value, label = 'amount') {
  if (!Number.isSafeInteger(value)) {
    throw new TypeError(`${label} must be an integer number of minor units, got ${value}`);
  }
}

/**
 * Parses decimal text such as "1,234.50" into minor units. More decimals than
 * the currency has is an error, never a silent rounding.
 */
export function parseAmount(text, currency) {
  const decimals = minorUnitDigits(currency);
  const match = AMOUNT_PATTERN.exec(String(text).trim());
  if (!match) throw new TypeError(`Not an amount: ${text}`);

  const [, sign, whole, fraction = ''] = match;
  if (fraction.length > decimals) {
    throw new RangeError(`${text} has more decimals than ${currency} allows`);
  }
  const digits = BigInt(whole.replaceAll(',', '') + fraction.padEnd(decimals, '0'));
  if (digits > BigInt(Number.MAX_SAFE_INTEGER)) {
    throw new TypeError(`${text} is too large to represent`);
  }
  const amount = Number(digits);
  return sign && amount !== 0 ? -amount : amount;
}

/** Decimal text without a currency code: "1,234.50", "-0.05", "1,500" for JPY. */
export function formatPlain(amount, currency) {
  const decimals = minorUnitDigits(currency);
  assertMinorUnits(amount);
  const digits = String(Math.abs(amount)).padStart(decimals + 1, '0');
  const major = digits.slice(0, digits.length - decimals);
  const minor = digits.slice(digits.length - decimals);
  const sign = amount < 0 ? '-' : '';
  return `${sign}${groupThousands(major)}${decimals > 0 ? `.${minor}` : ''}`;
}

/** Decimal text with the currency code in front: "USD 1,234.50". */
export function formatAmount(amount, currency) {
  return `${currency} ${formatPlain(amount, currency)}`;
}

/** Sums a list of minor-unit integers, checking each one. */
export function sumAmounts(amounts) {
  let total = 0;
  for (const amount of amounts) {
    assertMinorUnits(amount);
    total += amount;
  }
  assertMinorUnits(total, 'total');
  return total;
}

