// credited tracks the cumulative share of net credited, and reaches the
// line's tax exactly when the line is fully credited.
const done = credited[entry.lineIndex];
const netAfter = done.net + amount;
const tax = scaleRounded(line.tax, netAfter, line.net) - done.tax;
done.net = netAfter;
done.tax += tax;
available[entry.lineIndex] -= amount;

