import assert from 'node:assert/strict';
import test from 'node:test';

import {
  allocate,
  billingPeriods,
  buildInvoice,
  createSubscription,
  creditInvoiceInFull,
  definePlan,
  formatAmount,
  invoiceBalance,
  issueCreditNote,
  parseAmount,
  periodContaining,
  planChangeAmounts,
  renderStatement,
  renewalsAfter,
  sumAmounts,
  supportedCurrencies,
  minorUnitDigits,
} from '../src/index.mjs';

const base = { number: 'INV-1', customerId: 'cus_1', issueDate: '2024-03-01' };

test('a month-end anchor returns to the month end after February', () => {
  const ends = billingPeriods('2023-01-31', 1, 4).map((p) => p.end);
  assert.deepEqual(ends, ['2023-02-28', '2023-03-31', '2023-04-30', '2023-05-31']);
  const leap = billingPeriods('2024-01-31', 1, 2).map((p) => p.end);
  assert.deepEqual(leap, ['2024-02-29', '2024-03-31']);
});

test('a leap-day anchor renews on 29 February again in 2028', () => {
  const ends = billingPeriods('2024-02-29', 12, 4).map((p) => p.end);
  assert.deepEqual(ends, ['2025-02-28', '2026-02-28', '2027-02-28', '2028-02-29']);
  assert.deepEqual(renewalsAfter('2024-02-29', 12, '2025-03-01', 2), ['2026-02-28', '2027-02-28']);
  assert.equal(periodContaining('2024-01-31', 1, '2024-03-31').index, 2);
});

test('proration counts the change day as time left', () => {
  const period = { start: '2024-02-01', end: '2024-03-01' };
  assert.deepEqual(
    planChangeAmounts({ oldAmount: 2900, newAmount: 5800, period, changeDate: '2024-02-16' }),
    { credit: -1400, charge: 2800, net: 1400 },
  );
  const first = planChangeAmounts({ oldAmount: 2900, newAmount: 5800, period, changeDate: '2024-02-01' });
  assert.equal(first.credit, -2900);
  assert.equal(first.charge, 5800);
});

test('every currency parses and writes its own decimals', () => {
  assert.equal(parseAmount('2900', 'JPY'), 2900);
  assert.throws(() => parseAmount('29.5', 'JPY'), RangeError);
  assert.equal(parseAmount('1.5', 'KWD'), 1500);
  assert.equal(parseAmount('-0.001', 'KWD'), -1);
  assert.throws(() => parseAmount('1.0005', 'KWD'), RangeError);
  assert.equal(formatAmount(1500, 'KWD'), 'KWD 1.500');
  assert.equal(formatAmount(-5, 'KWD'), 'KWD -0.005');
  assert.equal(formatAmount(1234500, 'KWD'), 'KWD 1,234.500');
  assert.equal(formatAmount(0, 'JPY'), 'JPY 0');
  for (const code of supportedCurrencies()) {
    const text = formatAmount(123456789, code).slice(4).replaceAll(',', '');
    assert.equal(parseAmount(text, code), 123456789, code);
    assert.equal(text.includes('.'), minorUnitDigits(code) > 0, code);
  }
});

test('a KWD plan can be defined and its statement has three decimals', () => {
  const plan = definePlan({ code: 'team', prices: { KWD: '9.500' } });
  const sub = createSubscription({
    id: 's',
    customerId: 'c',
    anchor: '2024-03-10',
    plan,
    currency: 'KWD',
    taxRateBps: 500,
  });
  assert.equal(plan.prices.KWD, 9500);
  const invoice = buildInvoice({
    ...base,
    currency: sub.currency,
    lines: [{ description: 'Team', unitAmount: 9500, taxRateBps: 500 }],
  });
  assert.match(renderStatement(invoice), /Team +9\.500 +0\.000 +9\.500 +0\.475 +9\.975\n/);
  const jpy = buildInvoice({ ...base, currency: 'JPY', lines: [{ description: 'Team', unitAmount: 2900 }] });
  assert.match(renderStatement(jpy), /Team +2900 +0 +2900 +0 +2900\n/);
});

test('allocation gives leftovers to the largest remainders and mirrors negatives', () => {
  assert.deepEqual(allocate(100, [1, 1, 1]), [34, 33, 33]);
  assert.deepEqual(allocate(1, [3, 4, 3]), [0, 1, 0]);
  assert.deepEqual(allocate(100, [1, 1, 1, 0]), [34, 33, 33, 0]);
  assert.deepEqual(allocate(-100, [1, 1, 1]), [-34, -33, -33]);
  assert.deepEqual(allocate(5, [1, 1, 0]), [3, 2, 0]);
});

test('a discount never touches a free line', () => {
  const invoice = buildInvoice({
    ...base,
    currency: 'USD',
    discount: { fixed: 1 },
    lines: [
      { description: 'A', unitAmount: 1000 },
      { description: 'B', unitAmount: 1000 },
      { description: 'Free', unitAmount: 0 },
    ],
  });
  assert.deepEqual(invoice.lines.map((l) => l.discount), [1, 0, 0]);
});

function lcg(seed) {
  let state = seed;
  return (max) => {
    state = (state * 1103515245 + 12345) % 2 ** 31;
    return state % max;
  };
}

test('line tax adds up to the group tax and gross to the total', () => {
  const next = lcg(7);
  const rates = [0, 500, 900, 1000, 2100];
  for (let run = 0; run < 300; run += 1) {
    const lines = Array.from({ length: 1 + next(5) }, (_, i) => ({
      description: `L${i}`,
      unitAmount: next(5) === 0 ? -next(5000) : next(5000),
      taxRateBps: rates[next(rates.length)],
    }));
    const invoice = buildInvoice({ ...base, currency: 'USD', lines });
    assert.equal(sumAmounts(invoice.lines.map((l) => l.gross)), invoice.total);
    assert.equal(sumAmounts(invoice.lines.map((l) => l.tax)), invoice.taxTotal);
    for (const line of invoice.lines) {
      assert.ok(Math.abs(line.tax - (line.net * line.taxRateBps) / 10000) <= 1);
    }
  }
});

test('a swap at the same price shows tax on each line and owes none', () => {
  const invoice = buildInvoice({
    ...base,
    currency: 'USD',
    lines: [
      { description: 'Unused', unitAmount: -1050, taxRateBps: 1000 },
      { description: 'New', unitAmount: 1050, taxRateBps: 1000 },
    ],
  });
  assert.equal(invoice.taxTotal, 0);
  assert.equal(invoice.total, 0);
  assert.equal(sumAmounts(invoice.lines.map((l) => l.tax)), 0);
});

test('staged refunds end on zero and never exceed the amount paid', () => {
  const next = lcg(11);
  for (let run = 0; run < 200; run += 1) {
    const invoice = buildInvoice({
      ...base,
      currency: 'USD',
      discount: { percentBps: 100 * (1 + next(40)) },
      lines: Array.from({ length: 1 + next(4) }, (_, i) => ({
        description: `L${i}`,
        unitAmount: 1 + next(3000),
        taxRateBps: [900, 1000, 2100][next(3)],
      })),
    });
    const notes = [];
    for (let step = 0; step < 6; step += 1) {
      const index = next(invoice.lines.length);
      const left = invoice.lines[index].net - notes.reduce(
        (sum, n) => sum + n.lines.filter((l) => l.lineIndex === index).reduce((s, l) => s + l.net, 0),
        0,
      );
      if (left < 1) continue;
      const amount = 1 + next(left);
      notes.push(
        issueCreditNote(invoice, { number: `CN-${step}`, date: '2024-03-05', lines: [{ lineIndex: index, amount }] }, notes),
      );
      assert.ok(invoiceBalance(invoice, notes) >= 0);
    }
    notes.push(creditInvoiceInFull(invoice, { number: 'CN-F', date: '2024-03-06' }, notes));
    assert.equal(invoiceBalance(invoice, notes), 0);
  }
});

test('a credit above the discounted net is rejected', () => {
  const invoice = buildInvoice({
    ...base,
    currency: 'USD',
    discount: { percentBps: 5000 },
    lines: [{ description: 'A', unitAmount: 1000, taxRateBps: 1000 }],
  });
  assert.throws(
    () => issueCreditNote(invoice, { number: 'CN', date: '2024-03-05', lines: [{ lineIndex: 0, amount: 501 }] }),
    RangeError,
  );
});

